with up as (update public.artists a set spotify=x.u from json_to_recordset('[{"s":"ak-sports","u":"https://open.spotify.com/artist/7qiOBa5jCbTeyLY2Chw9ju"},{"s":"reble","u":"https://open.spotify.com/artist/3MsxNLVtDVGxjEaxgKAoi0"},{"s":"weird-sounding-dude","u":"https://open.spotify.com/artist/7IBheQbrrR0LDE5vSicwiY"}]'::json) as x(s text,u text) where a.slug=x.s and (a.spotify is null or a.spotify='') returning 1) select count(*) from up;